        if (iemGetEffHcrEl2NVx(pVCpu, pGstFeats) == 7)
            return iemCImplHlpNVMemReadU64(pVCpu, 0x108, puDst);
        *puDst = pVCpu->cpum.GstCtx.ContextIdr.u64;
